-- v0.9 👑 Merge tiers: Domains (3x3).
-- Nine plots of one type merged into a full 3x3 square can become that type's Domain — the tier above the Estate,
-- with its own world, economy (about 1.5x an Estate), a charter of 600 and a signature minigame:
--   Art Canvas → 🌌 Starlight Museum (Constellation)      Habitat → 🦢 Spirit Lake Sanctuary (Spirit Angler)
--   Farm → 🏰 Harvest Kingdom (Plough Run)                  Business → 🏢 Megacorp Spire (Lift Rush)
--   Arcade → 🛸 Neon Galaxy Park (Ring Toss)                Crystal Mine → 🌋 World's Core (Drill Dive)
--   Sky Island → 🔭 Celestial Observatory (Orbit Slingshot) Workshop → 🤖 Automaton Works (Circuit Connect)
--   Restaurant → 🎂 Sky Banquet Palace (Perfect Slice)      Dungeon → 👁️ Abyssal Throne (Rune Duel)
--   Paintbrawl → ⚡ Hall of Titans (Elemental Clash)
-- Type, Estate and Domain are one family: they merge together, and switching between them is free and keeps progress.
-- Merging keeps the highest tier the land still qualifies for; breaking a 3x3 drops a Domain to its Estate (while a
-- 2x2 remains) or to the base type. Estates and Domains also get doors at home.

insert into public.plot_kinds (id, name, description, sort) values
  ('museum', 'Starlight Museum', 'Domain: The whole sky, on one wall.', 40),
  ('sanctuary', 'Spirit Lake Sanctuary', 'Domain: Where the lake begins.', 41),
  ('kingdom', 'Harvest Kingdom', 'Domain: The granary of the realm.', 42),
  ('megacorp', 'Megacorp Spire', 'Domain: The very top of the spire.', 43),
  ('galaxypark', 'Neon Galaxy Park', 'Domain: The finale every night.', 44),
  ('core', 'World’s Core', 'Domain: The planet’s beating heart.', 45),
  ('observatory', 'Celestial Observatory', 'Domain: A window onto the dark.', 46),
  ('automaton', 'Automaton Works', 'Domain: Where the machines dream.', 47),
  ('banquet', 'Sky Banquet Palace', 'Domain: A table for the whole sky.', 48),
  ('abyss', 'Abyssal Throne', 'Domain: Who sits here is not here.', 49),
  ('titans', 'Hall of Titans', 'Domain: The top of the world.', 50)
on conflict (id) do nothing;

